import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
report=json.loads((ROOT/'dist/benchmark.json').read_text())
percent=lambda x:f'{100*x:.2f}%'
rows=[]
for key in ['tfidf','exact','dice','minilm','distiluse','mpnet']:
 model=report['models'][key];s=model['tests']['spelling'];w=model['tests']['syntax_proxy'];ci=f"95% pilot interval: {percent(s['rank1_ci95_low'])}–{percent(s['rank1_ci95_high'])}; {s['rank1_correct']}/{s['n']} correct"
 rows.append(f'''<tr data-model="{key}"><td>{html.escape(model['name'])}<span class="selected-model" hidden>Selected</span></td><td title="{ci}">{percent(s['rank1'])}</td><td>{percent(s['hit5'])}</td><td>{percent(w['rank1'])}</td><td>{percent(s['coverage'])}</td><td>{s['mrr']:.3f}</td><td>{percent(report['known_entry_control'][key]['accuracy'])}</td></tr>''')
section='''<section class="performance"><h2>Model performance</h2><p>Measured pilot: 50 spelling tests and 50 word-order tests per translation direction, using the same 400 queries for every method. Scores include exact matching and rejected queries. Transformer rows measure TF-IDF + quantized model reranking with CPU inference; browser output may vary slightly.</p><div class="table-wrap"><table id="performanceTable"><thead><tr><th>Model</th><th>Spelling Rank-1</th><th>Spelling Hit@5</th><th>Word-order recovery*</th><th>Spelling coverage</th><th>Spelling MRR</th><th>Known-entry lookup**</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p class="benchmark-note">Rank-1: correct translation at the first returned entry. Hit@5: correct translation within five entries. Coverage: queries receiving a result. Rejections count as incorrect. Each aggregate uses 200 queries per test. **Known-entry lookup checks 400 unchanged indexed sources; it does not measure generalization.</p><div class="direction-performance"><h3 id="directionHeading">Results by direction</h3><div class="table-wrap"><table><thead><tr><th>Direction</th><th>Spelling Rank-1</th><th>Spelling Hit@5</th><th>Word-order recovery*</th><th>Spelling coverage</th></tr></thead><tbody id="directionRows"></tbody></table></div><p>*Word-order recovery is a retrieval test, not grammatical accuracy. Independent, human-verified translation accuracy remains pending.</p></div><div class="benchmark-downloads"><a href="performance.csv" download>Download all results (CSV)</a><a href="benchmark.json" download>Benchmark details (JSON)</a></div></section>'''
p=ROOT/'dist/index.html';s=p.read_text();start=s.index('<section class="performance">');end=s.index('</section>',start)+len('</section>');s=s[:start]+section+s[end:];s=s.replace('<script src="performance.js" defer></script>','');s=s.replace('<script src="app.js" defer></script>','<script src="app.js" defer></script><script src="performance.js" defer></script>');p.write_text(s)
